import{_ as a,c as o,o as t,aj as r}from"./chunks/framework.BlveriQe.js";const b=JSON.parse('{"title":"Interface: Db3AliasOptions","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/Db3AliasOptions.md","filePath":"reference/js-bao-wss-client/api/interfaces/Db3AliasOptions.md"}'),s={name:"reference/js-bao-wss-client/api/interfaces/Db3AliasOptions.md"};function n(i,e,d,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / Db3AliasOptions</p><h1 id="interface-db3aliasoptions" tabindex="-1">Interface: Db3AliasOptions <a class="header-anchor" href="#interface-db3aliasoptions" aria-label="Permalink to “Interface: Db3AliasOptions”">​</a></h1><p>What <code>client.db3.getOrCreateWithAlias</code> looks up, and creates when the alias names nothing.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="alias" tabindex="-1">alias <a class="header-anchor" href="#alias" aria-label="Permalink to “alias”">​</a></h3><blockquote><p><strong>alias</strong>: <a href="./ResolveAliasParams.html"><code>ResolveAliasParams</code></a></p></blockquote><p>The alias: <code>scope: &quot;user&quot;</code> and an <code>aliasKey</code>; <code>userId</code> defaults to the caller.</p><hr><h3 id="allowunknowntype" tabindex="-1">allowUnknownType? <a class="header-anchor" href="#allowunknowntype" aria-label="Permalink to “allowUnknownType?”">​</a></h3><blockquote><p><code>optional</code> <strong>allowUnknownType?</strong>: <code>boolean</code></p></blockquote><p>In a build generated with <code>--known-types-only</code>, send the call even when <code>type</code> is not one the build was generated with. Only <code>true</code> skips the check. Read on the device; never sent.</p><hr><h3 id="metadata" tabindex="-1">metadata? <a class="header-anchor" href="#metadata" aria-label="Permalink to “metadata?”">​</a></h3><blockquote><p><code>optional</code> <strong>metadata?</strong>: <code>unknown</code></p></blockquote><p>The metadata blob of a db3 it creates.</p><hr><h3 id="permission" tabindex="-1">permission? <a class="header-anchor" href="#permission" aria-label="Permalink to “permission?”">​</a></h3><blockquote><p><code>optional</code> <strong>permission?</strong>: <code>&quot;owner&quot;</code> | <code>&quot;read-write&quot;</code> | <code>&quot;reader&quot;</code></p></blockquote><p>The alias user&#39;s level on a db3 it creates (default <code>owner</code>): <code>reader</code> or <code>read-write</code> writes no owner row and one row at that level, so a <code>reader</code> never holds write access. A level other than <code>owner</code> needs an app owner or admin (or a function declaring <code>db3:setOwnerRow</code>); a member is refused 403. Ignored when the alias already names a db3.</p><hr><h3 id="tags" tabindex="-1">tags? <a class="header-anchor" href="#tags" aria-label="Permalink to “tags?”">​</a></h3><blockquote><p><code>optional</code> <strong>tags?</strong>: <code>string</code>[]</p></blockquote><p>Tags of a db3 it creates.</p><hr><h3 id="title" tabindex="-1">title? <a class="header-anchor" href="#title" aria-label="Permalink to “title?”">​</a></h3><blockquote><p><code>optional</code> <strong>title?</strong>: <code>string</code></p></blockquote><p>The title of a db3 it creates.</p><hr><h3 id="type" tabindex="-1">type? <a class="header-anchor" href="#type" aria-label="Permalink to “type?”">​</a></h3><blockquote><p><code>optional</code> <strong>type?</strong>: <code>string</code></p></blockquote><p>The db3&#39;s type: installed on a db3 it creates, and otherwise a statement about the db3 the alias names, refused 409 <code>DB3_TYPE_MISMATCH</code> when that db3 is not of this type.</p>',33)])])}const u=a(s,[["render",n]]);export{b as __pageData,u as default};
